/* MUTANT: one refusal broken on purpose. The gate MUST go red against this
 * file. Generated by mut/make.py; never edited by hand.
 */
/* <ov-position> - a position labelled by how it was worked out, with its
 * integrity bound.
 *
 * For industrial,
 * aegis, terminal, machina, vector and holo. Maritime and aviation arrived at
 * the same element from opposite ends: a lat/lon whose MODE comes from the
 * receiver's own mode flag rather than from the source's name, and a point
 * drawn inside TWO rings - how accurate it claims to be, and how far it may
 * be wrong without anyone knowing - each checked against a declared
 * requirement.
 *
 *   <ov-position label="OWN SHIP" requirement="10"
 *                requirement-for="3 NM SEPARATION"></ov-position>
 *   p.fix = {
 *     lat: 42.1234, lon: -70.5678,
 *     mode: 'dr', since: t - 11880000,      // fix | augmented | dr | held | manual
 *     accuracy: 12, containment: 185, containmentP: 1e-7,
 *     integrity: 'low', integrityBy: 'plausibility checks on one receiver',
 *     second: { id: 'LORAN-C', lat, lon, shares: 'gyro and speed log' },
 *   };
 *
 * ── THE REFUSAL ───────────────────────────────────────────────────────────
 *
 * 🔴 A DERIVED POSITION IS NEVER STYLED AS A FIX. The mode badge is taken
 * from the mode flag and never from the label on the wire, and a dead
 * reckoned or held position says so, with the time of the last valid fix and
 * how long ago that was. NTSB MAR-97/01, the Royal Majesty: "Raytheon
 * designed the 920 GPS to identify itself as a 'GP' talker regardless of GPS
 * or DR mode", and "the central console display switched from GPS to
 * DR-derived positions without changing its display in any perceivable way or
 * notifying the crew". The ship ran aground.
 *
 * ⚠️ NOTE WHY THE KIT'S EXISTING QUALIFIERS CANNOT DO THIS. The NTSB's bench
 * tests found the receiver had TWO failure outputs: with speed and course
 * input the position kept "updating based on the DR data and the last GPS
 * position"; without it the data "stay fixed at the last position". Only the
 * second is `frozen`, and neither is `stale` - a DR position is fresh,
 * moving, and machine-made. What is wrong with it is how it was COMPUTED,
 * which no qualifier about age or stuckness can express. MSC.401(95) §3.13
 * requires the state be said outright: "the last known position and the time
 * of last valid fix, with the explicit indication of the state so that no
 * ambiguity can exist, should be output until normal operation is resumed".
 *
 * And five that follow from it:
 *
 * 1. ONE RING NEVER STANDS FOR BOTH CLAIMS. Accuracy is where the position
 *    probably is; integrity containment is how far out it could be without
 *    the system noticing. They are different numbers answering different
 *    questions, so they are two rings, both labelled, never one.
 * 2. A CONTAINMENT WITH NO STATED PROBABILITY IS NOT A BOUND. A radius given
 *    without the probability of exceeding it is drawn as an OPEN ring - broken,
 *    running off the plot - and reads CONTAINMENT UNBOUNDED. A tight circle
 *    with nothing behind it is the most confident thing this element can draw
 *    and the least earned.
 * 3. INTEGRITY `none` IS NEVER SHOWN AS CHECKED, AND `medium` MUST BE EARNED.
 *    MSC.1/Circ.1575 ¶47 grades it: None is "Unavailable integrity
 *    evaluation"; Low is checks "of data provided by single sensors"; Medium
 *    needs "different sensors, systems, services, and sources with
 *    uncorrelated error parts as far as possible"; High needs an "estimated
 *    accuracy (protection level)". ¶85.1: level None "should be regarded as
 *    having no integrity". So a cross-check against a second source that
 *    SHARES inputs does not earn Medium: it reads CROSS-CHECK NOT INDEPENDENT
 *    and names what the two share. (Applying ¶47.3's "uncorrelated error
 *    parts" this way is INFERRED; the NTSB notes the autopilot's DR and the
 *    GPS's DR shared gyro and speed inputs and ran essentially identical.)
 * 4. DIGITS ARE CAPPED BY THE STATED ACCURACY. MSC.401(95) §3.6.1: position
 *    should be shown "to a precision reflective of the accuracy of the
 *    position information, up to four (4) decimal places". A position known
 *    to half a kilometre is not printed to four decimals, and the element
 *    says which accuracy capped it.
 * 5. A BOUND THAT MISSES THE REQUIREMENT DOES NOT HIDE THE POSITION. The
 *    point stays and the block says what it may NOT be used for, which is how
 *    ATC does it: FAA JO 7110.65 5-5-4, "When displaying ISR in the data
 *    block- 5 miles", the indicator meaning the track's confidence is such
 *    that the closer separation standards "cannot be used". Withholding the
 *    position would be worse than qualifying it; qualifying it silently would
 *    be worse still.
 *
 * No `role="img"` on the host: its children would become presentational and
 * the mode, integrity and cross-check rows would never be read. The rings are
 * the only aria-hidden part, and every radius they
 * draw is also a row of text.
 *
 * Drawn on each update and at most once a second while on screen, for the age
 * of the last valid fix. Nothing runs every frame.
 *
 * A DR position carries `estimated` WITH ITS CAUSE. `containment-unbounded`
 * is not yet in ov-refusal.js's REASONS.
 */

import { define, watchSeen, isSeen, whenArrived } from '../../../src/ov-core.js';
import '../../../src/ov-source.js';

const M_PER_DEG = 111_320;      // one degree of latitude, near enough
const MAX_PLACES = 4;           // MSC.401(95) §3.6.1

/* Every mode is a WORD the element writes, and every derived one says what it
 * was derived from. `fix` is the only mode that is a measurement. */
const MODE = {
  fix: { word: 'FIX', derived: false },
  augmented: { word: 'AUGMENTED', derived: false },
  dr: { word: 'DEAD RECKONED', derived: true },
  held: { word: 'HELD AT LAST FIX', derived: true },
  manual: { word: 'MANUAL', derived: true },
};
/* MSC.1/Circ.1575 ¶47, in its own order. */
const INTEGRITY = {
  none: { word: 'NONE', rank: 0, std: 'unavailable integrity evaluation' },
  low: { word: 'LOW', rank: 1, std: 'checks on single sensors or sources' },
  medium: { word: 'MEDIUM', rank: 2, std: 'checks across sources with uncorrelated errors' },
  high: { word: 'HIGH', rank: 3, std: 'estimated accuracy, a protection level' },
};

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const setText = (el, t) => { if (el && el.textContent !== t) el.textContent = t; };
const setAttr = (el, k, v) => {
  if (!el) return;
  if (v === null) { if (el.hasAttribute(k)) el.removeAttribute(k); } else if (el.getAttribute(k) !== v) el.setAttribute(k, v);
};
const num = (raw) => (raw === null || raw.trim() === '' ? null : Number(raw));
const finite = (v) => v !== null && Number.isFinite(v);
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const clock = (ms) => new Date(ms).toTimeString().slice(0, 8);

const dur = (s) => {
  const n = Math.max(0, Math.round(s));
  if (n < 60) return `${n}s`;
  if (n < 3600) return `${Math.floor(n / 60)}m ${String(n % 60).padStart(2, '0')}s`;
  return `${Math.floor(n / 3600)}h ${String(Math.floor((n % 3600) / 60)).padStart(2, '0')}m`;
};
/* Distances are read against each other, so they share one scheme. */
const metres = (m) => (m === null || !Number.isFinite(m) ? '—'
  : m >= 1852 ? `${(m / 1852).toFixed(m / 1852 >= 10 ? 0 : 1)} NM`
    : m >= 1000 ? `${(m / 1000).toFixed(1)} km`
      : `${Math.round(m)} m`);
/* A probability is read as its exponent, because that is how the standards
 * write it and because "0.0000001" cannot be compared at a glance. */
const prob = (p) => {
  if (p === null || !Number.isFinite(p) || p <= 0) return null;
  const e = Math.round(Math.log10(p));
  return Math.abs(p - 10 ** e) < 10 ** e * 0.05 ? `1e${e}` : p.toExponential(1);
};

let serial = 0;

export class OvPosition extends HTMLElement {
  static observedAttributes = ['src', 'label', 'requirement', 'requirement-for', 'source'];

  /* Our clock, in epoch ms. Replaceable so a test can drive time. */
  static now = () => Date.now();

  constructor() {
    super();
    this._fix = null;
    this._malformed = 0;
    this._queue = [];
    this._said = '';
    this._uid = `ov-position-${++serial}`;
  }

  connectedCallback() {
    if (!this._built) this.build();
    this.fetchSrc();
    this.bindSource();
    this.evaluate();
    // The age of the last valid fix moves without a new fix arriving.
    // 🔴 A LIVE LOOP WAITS FOR THE PAGE. ov-core holds every feed, frame and
    // timer until the first screenful has landed, so the tick is started
    // through whenArrived rather than here; it fires at once on an element
    // upgraded after arrival, which is what lazy loading makes of this one.
    if (!this._unarrive) this._unarrive = whenArrived(() => this.startTicking());
    if (!this._unwatch) this._unwatch = watchSeen(this, () => this.evaluate());
  }

  startTicking() {
    if (this._timer || !this.isConnected) return;
    this._timer = setInterval(() => { if (isSeen(this)) this.evaluate(); }, 1000);
  }

  disconnectedCallback() {
    clearInterval(this._timer);
    this._timer = 0;
    if (this._unarrive) this._unarrive();
    this._unarrive = null;
    if (this._unwatch) this._unwatch();
    this._unwatch = null;
    if (this.unsub) this.unsub();
    this.unsub = null;
  }

  attributeChangedCallback(name) {
    if (!this._built) return;
    if (name === 'src') { this.fetchSrc(); return; }
    if (name === 'source') this.bindSource();
    this.evaluate();
  }

  /* A scene from a file, so the element renders as plain markup on a page that
   * carries no script: `<ov-position src="models/position-x.json">`. The same
   * route the kit's other data-driven elements take (ov-consistency,
   * ov-coverage), and the reason a reference page can show one at all.
   *
   * 🔴 A FETCH THAT FAILS LEAVES NO SCENE, NOT A STALE ONE. The element then
   * says what it says with no data, which is its own refusal rather than the
   * last thing that happened to load. The src check after the await is for a
   * src changed while the request was in flight: the loser must not win.
   */
  async fetchSrc() {
    const src = this.getAttribute('src');
    if (!src) return;
    let data = null;
    try {
      const r = await fetch(src);
      if (!r.ok) throw new Error(String(r.status));
      data = await r.json();
    } catch {
      data = null;
    }
    if (this.getAttribute('src') !== src) return;
    this.fix = data;
  }

  bindSource() {
    if (this.unsub) this.unsub();
    this.unsub = null;
    const name = this.getAttribute('source');
    if (!name || !window.Overscan?.subscribe) return;
    this.unsub = window.Overscan.subscribe(name, (x) => { this.fix = x; });
  }

  /* ---- taking a position in --------------------------------------------- */

  set fix(f) {
    if (!f || typeof f !== 'object') { this._malformed++; this._fix = null; this.evaluate(); return; }
    const n = (v) => (v === null || v === undefined ? null : (Number.isFinite(Number(v)) ? Number(v) : null));
    // 🔴 The mode is read from the mode flag ONLY. An unrecognised mode is not
    // quietly a fix: it is a mode this element does not know.
    const mode = Object.hasOwn(MODE, f.mode) ? f.mode : null;
    if (f.mode !== undefined && mode === null) this._malformed++;
    this._fix = {
      lat: n(f.lat), lon: n(f.lon),
      mode,
      augmentedBy: f.augmentedBy ? String(f.augmentedBy) : null,
      // A stored scene states `ago` in seconds before now rather than a
      // wall-clock time, which would read as years old a week later.
      since: n(f.since) !== null ? n(f.since)
        : n(f.ago) !== null ? OvPosition.now() - n(f.ago) * 1000 : null,
      accuracy: n(f.accuracy),
      containment: n(f.containment),
      containmentP: n(f.containmentP),
      integrity: Object.hasOwn(INTEGRITY, f.integrity) ? f.integrity : null,
      integrityBy: f.integrityBy ? String(f.integrityBy) : null,
      second: f.second && typeof f.second === 'object' ? {
        id: f.second.id === undefined ? null : String(f.second.id),
        lat: n(f.second.lat), lon: n(f.second.lon),
        // A string names what the two share; true says "shares, unspecified".
        shares: f.second.shares === true ? 'inputs' : f.second.shares ? String(f.second.shares) : null,
      } : null,
    };
    this.evaluate();
  }

  get fix() { return this._fix; }

  /* ---- what the position is worth --------------------------------------- */

  /* Refusal 4: the finest step that is not finer than the stated accuracy. */
  places(accuracy) {
    if (!finite(accuracy) || accuracy <= 0) return null;
    return clamp(Math.ceil(Math.log10(M_PER_DEG / accuracy)), 0, MAX_PLACES);
  }

  evaluate() {
    if (!this._built) return this._report;
    const now = OvPosition.now();
    const req = num(this.getAttribute('requirement'));
    const f = this._fix;
    const r = {
      state: 'empty', mode: null, derived: false, ageS: null, places: null,
      integrity: null, capped: false, unbounded: false, missesReq: false,
      notIndependent: null, discrepancy: null, why: '',
    };
    const done = () => { this._report = r; this.paint(r, req); this.announce(r); return r; };

    if (!f) { r.why = 'NO POSITION'; return done(); }
    if (!finite(f.lat) || !finite(f.lon)) {
      r.state = 'nofix';
      r.why = 'NO POSITION';
      return done();
    }
    // A position with no mode flag is not a fix by default: the whole point of
    // the element is that the mode is never assumed.
    if (f.mode === null) {
      r.state = 'nomode';
      r.why = 'MODE NOT STATED · this position does not say how it was derived';
      return done();
    }
    r.mode = f.mode;
    r.derived = MODE[f.mode].derived;

    if (r.derived) {
      if (finite(f.since)) r.ageS = (now - f.since) / 1000;
      r.state = 'derived';
    } else {
      r.state = 'fix';
    }

    r.places = this.places(f.accuracy);
    r.capped = r.places !== null && r.places < MAX_PLACES;

    // Refusal 2: a radius with no probability is not a bound.
    r.unbounded = finite(f.containment) && prob(f.containmentP) === null;

    // Refusal 3: integrity as graded, and medium only when earned.
    r.integrity = f.integrity;
    if (false && f.second && f.second.shares) {  // MUTANT: take the claim as given
      r.notIndependent = f.second.shares;
      r.integrity = 'low';          // demoted, and the element says why
    }

    if (f.second && finite(f.second.lat) && finite(f.second.lon)) {
      const dLat = (f.second.lat - f.lat) * M_PER_DEG;
      const dLon = (f.second.lon - f.lon) * M_PER_DEG * Math.cos((f.lat * Math.PI) / 180);
      r.discrepancy = Math.hypot(dLat, dLon);
    }

    // Refusal 5: the bound against the declared requirement.
    const bound = r.unbounded ? Infinity : finite(f.containment) ? f.containment : null;
    if (finite(req) && req > 0 && bound !== null) r.missesReq = bound > req;

    const bits = [];
    if (r.derived) {
      bits.push(MODE[f.mode].word
        + (finite(f.since) ? ` FROM FIX AT ${clock(f.since)} · ${dur(r.ageS)} AGO` : ' · NO TIME OF LAST FIX'));
    }
    if (r.unbounded) bits.push('CONTAINMENT UNBOUNDED');
    if (r.integrity === 'none' || r.integrity === null) bits.push('INTEGRITY NOT EVALUATED');
    if (r.notIndependent) bits.push(`CROSS-CHECK NOT INDEPENDENT · SHARES ${r.notIndependent.toUpperCase()}`);
    r.why = bits.join(' · ');
    return done();
  }

  get report() { return this._report; }

  /* Announcements from one update are JOINED into one: several writes to a
   * live region in one task are heard as the last only (d7c18ae). */
  say(text) {
    this._queue.push(text);
    if (this._flushing) return;
    this._flushing = true;
    queueMicrotask(() => {
      this._flushing = false;
      const t = this._queue.join('; ');
      this._queue = [];
      const region = this.querySelector('.ov-position__say');
      if (region) { region.textContent = ''; region.textContent = t; }
    });
  }

  /* 🔴 A CHANGE OF MODE IS THE ANNOUNCEMENT THIS ELEMENT EXISTS FOR. The Royal
   * Majesty's console changed mode "without changing its display in any
   * perceivable way or notifying the crew", so mode is the first thing in the
   * key and a change to a derived mode is always spoken. */
  announce(r) {
    const key = `${r.state}|${r.mode}|${r.integrity}|${r.unbounded}|${r.missesReq}|${r.notIndependent}`;
    if (key === this._said) return;
    const first = this._said === '';
    const prev = this._said;
    this._said = key;
    if (first) return;
    if (r.derived) this.say(`${this.label()}: no longer a fix, ${MODE[r.mode].word.toLowerCase()}${r.ageS !== null ? `, last fix ${dur(r.ageS)} ago` : ''}`);
    else if (prev.includes('derived')) this.say(`${this.label()}: fix restored`);
    if (r.unbounded) this.say(`${this.label()}: containment unbounded`);
    if (r.notIndependent) this.say(`${this.label()}: cross-check not independent, shares ${r.notIndependent}`);
    if (r.missesReq) this.say(`${this.label()}: ${this.reqFor()}`);
  }

  label() { return this.getAttribute('label') || 'POSITION'; }
  reqFor() {
    const f = this.getAttribute('requirement-for');
    return f ? `not for ${f.toLowerCase()}` : 'does not meet the stated requirement';
  }

  /* ---- drawing ---------------------------------------------------------- */

  build() {
    this._built = true;
    this.innerHTML = `
      <div class="ov-position__modeline">
        <span class="ov-aside ov-position__label"></span>
        <div class="ov-state ov-state--badge ov-position__mode">
          <span class="ov-position__modeword ov-state__word"></span>
        </div>
        <span class="ov-aside ov-position__why"></span>
      </div>
      <div class="ov-position__body">
        <div class="ov-position__rings" aria-hidden="true">
          <svg class="ov-position__svg" viewBox="-100 -100 200 200">
            <circle class="ov-position__req" r="0"/>
            <circle class="ov-position__cont" r="0"/>
            <circle class="ov-position__acc" r="0"/>
            <line class="ov-position__link" x1="0" y1="0" x2="0" y2="0"/>
            <circle class="ov-position__secpt" r="2.5" cx="0" cy="0"/>
            <path class="ov-position__pt" d="M-6 0h12M0 -6v12"/>
          </svg>
          <div class="ov-position__ringlabels"></div>
        </div>
        <div class="ov-position__read">
          <div class="ov-position__latlon"></div>
          <div class="ov-aside ov-position__cap"></div>
          <dl class="ov-position__facts">
            <div><dt>ACCURACY 95%</dt><dd class="ov-position__accv"></dd></div>
            <div><dt>CONTAINMENT</dt><dd class="ov-position__contv"></dd></div>
            <div><dt>INTEGRITY</dt><dd class="ov-position__intv"></dd></div>
            <div class="ov-position__secrow"><dt>SECOND SOURCE</dt><dd class="ov-position__secv"></dd></div>
          </dl>
        </div>
      </div>
      <div class="ov-position__notfor"></div>
      <div class="ov-aside ov-position__rulebox"></div>
      <div class="ov-position__foot"></div>
      <div class="ov-position__say" aria-live="polite"></div>`;
    this.setAttribute('role', 'group');
  }

  /* Latitude and longitude, to no more decimals than the accuracy supports. */
  latlon(r, f) {
    if (!finite(f.lat) || !finite(f.lon)) return '—';
    // With no accuracy stated there is nothing to cap the digits BY, so the
    // element shows the coarsest it offers rather than the finest.
    const d = r.places === null ? 0 : r.places;
    const ns = f.lat >= 0 ? 'N' : 'S';
    const ew = f.lon >= 0 ? 'E' : 'W';
    return `${Math.abs(f.lat).toFixed(d)}° ${ns}   ${Math.abs(f.lon).toFixed(d)}° ${ew}`;
  }

  paint(r, req) {
    const q = (s) => this.querySelector(s);
    const f = this._fix;
    setText(q('.ov-position__label'), this.label());
    setText(q('.ov-position__rulebox'), finite(req) && req > 0
      ? `NEEDS ${metres(req)}${this.getAttribute('requirement-for') ? ` · ${this.getAttribute('requirement-for').toUpperCase()}` : ''}`
      : 'NO REQUIREMENT');

    setAttr(this, 'data-ov-state', r.state);
    // A derived position keeps its number, so it is a NOTE - but the stamp
    // inverts, which is the point: it stops looking printed.
    setAttr(q('.ov-position__mode'), 'data-ov-tone',
      r.state === 'fix' ? 'ok' : r.state === 'derived' ? 'note' : 'bad');
    setAttr(this, 'data-ov-mode', r.mode);
    setAttr(this, 'data-ov-derived', r.derived ? '' : null);
    setAttr(this, 'data-ov-integrity', r.integrity);

    // A position that never said how it was derived is a refusal; a derived
    // one keeps its number and carries `estimated` with its cause.
    setAttr(this, 'data-ov-refusal',
      r.state === 'nofix' || r.state === 'empty' ? 'unknown'
        : r.state === 'nomode' ? 'unknown'
          : r.unbounded ? 'containment-unbounded' : null);
    setAttr(this, 'data-ov-qualified', r.derived ? 'estimated' : null);

    const modeWord = r.state === 'nomode' ? 'MODE NOT STATED'
      : r.state === 'nofix' || r.state === 'empty' ? 'NO POSITION'
        : MODE[r.mode].word + (r.mode === 'augmented' && f.augmentedBy ? ` BY ${f.augmentedBy.toUpperCase()}` : '');
    setText(q('.ov-position__modeword'), modeWord);
    setText(q('.ov-position__why'), r.why);
    setAttr(this, 'data-ov-qualifier-text', r.derived ? r.why.toLowerCase() : null);

    const noPos = r.state === 'empty' || r.state === 'nofix';
    setText(q('.ov-position__latlon'), noPos ? '—' : this.latlon(r, f));
    setText(q('.ov-position__cap'), noPos ? ''
      : r.places === null ? 'NO ACCURACY STATED · DIGITS NOT CAPPED, SO NOT SHOWN'
        : r.capped ? `DIGITS CAPPED BY ±${metres(f.accuracy)} ACCURACY · ${r.places} DECIMALS`
          : `${r.places} DECIMALS · THE MOST THIS BLOCK SHOWS`);

    setText(q('.ov-position__accv'), noPos ? '—' : finite(f.accuracy) ? `±${metres(f.accuracy)}` : 'NOT STATED');
    const p = f ? prob(f.containmentP) : null;
    setText(q('.ov-position__contv'), noPos ? '—'
      : !finite(f.containment) ? 'NOT STATED'
        : p ? `±${metres(f.containment)} at ${p}/h` : `±${metres(f.containment)} · UNBOUNDED, NO PROBABILITY GIVEN`);
    setAttr(q('.ov-position__contv'), 'data-ov-unbounded', r.unbounded ? '' : null);

    const ig = r.integrity ? INTEGRITY[r.integrity] : null;
    setText(q('.ov-position__intv'), !ig ? 'NOT EVALUATED'
      : `${ig.word} · ${r.notIndependent ? `demoted: ${INTEGRITY[f.integrity].word} claimed, cross-check shares ${r.notIndependent}` : f.integrityBy || ig.std}`);

    const secRow = q('.ov-position__secrow');
    const hasSecond = !!(f && f.second);
    secRow.hidden = !hasSecond;
    if (hasSecond) {
      setText(q('.ov-position__secv'),
        `${f.second.id || 'UNNAMED'} · ${r.discrepancy === null ? 'NO POSITION' : `${metres(r.discrepancy)} away`}`
        + (f.second.shares ? ` · SHARES ${f.second.shares.toUpperCase()}` : ' · INDEPENDENT'));
      setAttr(secRow, 'data-ov-shares', f.second.shares ? '' : null);
    }

    // Refusal 5: what it may not be used for, not instead of the position.
    const notFor = r.missesReq
      ? `${this.getAttribute('requirement-for') ? `ISR · ${this.getAttribute('requirement-for').toUpperCase()} NOT AVAILABLE` : 'DOES NOT MEET THE STATED REQUIREMENT'}`
        + ` · BOUND ${r.unbounded ? 'UNBOUNDED' : metres(f.containment)} AGAINST ${metres(req)} REQUIRED`
      : '';
    setText(q('.ov-position__notfor'), notFor);

    this.setAttribute('aria-label', noPos
      ? `${this.label()}: ${modeWord.toLowerCase()}`
      : `${this.label()}: ${this.latlon(r, f).replace(/\s+/g, ' ')}, ${modeWord.toLowerCase()}`
        + `${r.why ? `, ${r.why.toLowerCase()}` : ''}${notFor ? `, ${notFor.toLowerCase()}` : ''}`);

    this.paintRings(r, req);
    setText(q('.ov-position__foot'), this._malformed
      ? `${this._malformed} reading${this._malformed > 1 ? 's' : ''} the element could not read` : '');
  }

  paintRings(r, req) {
    const q = (s) => this.querySelector(s);
    const f = this._fix;
    const labels = q('.ov-position__ringlabels');
    const noPos = !f || r.state === 'empty' || r.state === 'nofix';
    const rings = q('.ov-position__rings');
    rings.hidden = noPos;
    if (noPos) { if (labels.innerHTML) labels.innerHTML = ''; return; }

    // One scale for every radius, so the two rings can be compared by eye.
    // An unbounded containment has no radius to scale by, so it is drawn AT
    // the edge, broken, rather than given a size it does not have.
    const real = [f.accuracy, r.unbounded ? null : f.containment, req, r.discrepancy]
      .filter((v) => finite(v) && v > 0);
    const max = real.length ? Math.max(...real) : 1;
    const span = max * 1.3;
    const R = (m) => clamp((m / span) * 100, 0, 100);

    // 🔴 `hidden` is an HTMLElement property: on an SVG element `el.hidden =
    // true` sets a plain JS property and nothing else - no attribute, no
    // effect, and a ring that stays drawn. Inside the SVG it must be the
    // ATTRIBUTE, which the stylesheet then acts on.
    const hide = (el, show) => setAttr(el, 'hidden', show ? null : '');
    const set = (sel, m) => {
      const el = q(sel);
      const show = finite(m) && m > 0;
      setAttr(el, 'r', show ? String(R(m)) : '0');
      hide(el, show);
    };
    set('.ov-position__acc', f.accuracy);
    set('.ov-position__req', finite(req) && req > 0 ? req : null);
    // The containment ring: sized when bounded, at the edge when not.
    const cont = q('.ov-position__cont');
    if (r.unbounded) {
      setAttr(cont, 'r', '99');
      setAttr(cont, 'data-ov-unbounded', '');
      hide(cont, true);
    } else {
      setAttr(cont, 'data-ov-unbounded', null);
      set('.ov-position__cont', f.containment);
    }

    // The second source, as a point at its true offset, with a link to ours.
    const sec = q('.ov-position__secpt');
    const link = q('.ov-position__link');
    const hasSec = r.discrepancy !== null && f.second;
    hide(sec, hasSec);
    hide(link, hasSec);
    if (hasSec) {
      const dLat = (f.second.lat - f.lat) * M_PER_DEG;
      const dLon = (f.second.lon - f.lon) * M_PER_DEG * Math.cos((f.lat * Math.PI) / 180);
      const x = clamp((dLon / span) * 100, -97, 97);
      const y = clamp((-dLat / span) * 100, -97, 97);
      setAttr(sec, 'cx', x.toFixed(2));
      setAttr(sec, 'cy', y.toFixed(2));
      setAttr(link, 'x2', x.toFixed(2));
      setAttr(link, 'y2', y.toFixed(2));
    }

    /* 🔴 EVERY RADIUS DRAWN IS ALSO A WORD. They were placed on their own
     * rings, which read well until two radii were close: the spacing was a
     * percentage of the plot and a percentage is smaller than a label is tall
     * once the plot shrinks, so ACCURACY and CONTAINMENT overprinted on most
     * cards. Tuning the number would have moved the size at which it breaks
     * rather than fixing it.
     *
     * So they are a KEYED STACK in the corner instead, in normal flow, where
     * overlapping is not a thing that can happen. Each key is drawn with its
     * own ring's stroke - solid for accuracy, dashed for containment, dotted
     * for the requirement - so a row still says which circle it belongs to,
     * and the rows run outermost first, the order the eye reads the rings in. */
    const rows = [];
    if (finite(f.accuracy) && f.accuracy > 0) rows.push({ cls: 'acc', t: `ACCURACY ${metres(f.accuracy)}`, r: R(f.accuracy) });
    if (r.unbounded) rows.push({ cls: 'cont', t: 'CONTAINMENT UNBOUNDED', r: 99 });
    else if (finite(f.containment) && f.containment > 0) rows.push({ cls: 'cont', t: `CONTAINMENT ${metres(f.containment)}`, r: R(f.containment) });
    if (finite(req) && req > 0) rows.push({ cls: 'req', t: `REQUIRED ${metres(req)}`, r: R(req) });
    rows.sort((a, b) => b.r - a.r);
    const html = rows.map((row) => `<span class="ov-position__rl" data-ring="${row.cls}">`
      + `<i></i>${esc(row.t)}</span>`).join('');
    if (labels.innerHTML !== html) labels.innerHTML = html;
  }
}

define('ov-position', OvPosition);
